struct task *window_task;

struct Window *Programs;

static void resize_text_editor(Window *window, s32 old_width, s32 old_height) {
    if (!window || !window->buffer || window->width < 16 || window->height < 36)
        return;

    // Функция для отрисовки внутрь окна при изменении его размера
    // Если у вас постоянный размер, можете оставить его так
}

#define FONT_WIDTH 8
#define FONE_HEIGHT 16
#define START_TEXT 3
#define PADDING_ICON_TEXT 10
#define WIDTH_PROG 90
#define HEIGHT_PROG 90
#define MAX_LEN_NAME 10
#define SIZE_ICON 64  //размер иконки 64x64

u32 row = START_TEXT;
u32 col = HEIGHT_PROG;
u32 text_width = 0;
u32 len_name = 0;

static void clearframe_program(u32 color) {
    window_fill_rect(Programs, 0, 0, Programs->width, Programs->height, color);
}

static void draw_icon_program(u32 *icon) {
    u32 x = row + WIDTH_PROG / 2 - SIZE_ICON / 2;
    u32 y = col - HEIGHT_PROG + 20;
    
    drawimage(Programs, icon, 64, 64, x, y);
}

