static u32 parse_octal(const char *str, size_t size) {
    u32 val = 0;
    for (size_t i = 0; i < size; i++) {
        char c = str[i];
        if (c == '\0' || c == ' ') {
            break;
        }
        if (c >= '0' && c <= '7') {
            val = (val << 3) | (c - '0');
        }
    }
    return val;
}

